/* Dark mode: restore the original dark shades (--dark-xxxxxx vars); light mode keeps the theme colours. */
(function(){var H=["1e293b", "f1f5f9"];function go(){var c=(window.appsmith&&appsmith.theme&&appsmith.theme.colors)||{};var b=String(c.backgroundColor||'').toLowerCase();if(!b&&document.body){var p=document.createElement('i');p.style.color='var(--appsmith-theme-backgroundColor, rgb(1, 2, 3))';document.body.appendChild(p);b=getComputedStyle(p).color;document.body.removeChild(p);if(b==='rgb(1, 2, 3)')b='';}if(!b)return false;if(!/^(#fff(fff)?|white|rgba?\(255, ?255, ?255(, ?1)?\))$/.test(b))H.forEach(function(x){document.documentElement.style.setProperty('--dark-'+x,'#'+x);});return true;}(function t(n){if(!go()&&n>0)setTimeout(function(){t(n-1);},100);})(100);})();
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
var NUM={'Days Late':1,'Days of Service':1,'Days To Next Expected Due Date':1};
function render(model){
  var root=document.getElementById('root'); if(!root) return;
  var rows=(model&&model.rows)||[];
  if(!rows.length){ root.innerHTML='<div class="empty">No data available</div>'; return; }
  var cols=Object.keys(rows[0]);
  var h='<table class="wo"><thead><tr>';
  cols.forEach(function(c){ h+='<th>'+esc(c)+'</th>'; });
  h+='</tr></thead><tbody>';
  rows.forEach(function(r){
    h+='<tr>';
    cols.forEach(function(c){ h+='<td class="'+(NUM[c]?'num':'nowrap')+'">'+esc(r[c])+'</td>'; });
    h+='</tr>';
  });
  h+='</tbody></table>';
  root.innerHTML=h;
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(function(m){ render(m); }); });

